SELECT task_processing_id, ctrl_cmd_sequence_id, request_control_command_id, task_processing_start_time, task_processing_result_msg, task_processing_status, task_processing_end_time FROM msa_task_processing_info WHERE 1=1
and task_processing_id = #{taskProcessingId}
and ctrl_cmd_sequence_id = #{ctrlCmdSequenceId}
and request_control_command_id = #{requestControlCommandId}
and task_processing_status = #{taskProcessingStatus}
order by task_processing_id desc

